WITH matched_keys AS (SELECT dept_name, location FROM departments EXCEPT ALL SELECT dept_name, location FROM departments WHERE location <> 'New York'), verified AS (SELECT s.* FROM departments s JOIN matched_keys k ON s.dept_name = k.dept_name AND s.location = k.location) SELECT location, COUNT(*) FILTER (WHERE dept_name = 'Finance') AS finance_rows, ROUND(SUM(budget) / NULLIF(COUNT(CASE WHEN dept_name = 'Engineering' THEN 1 END), 0), 2) AS budget_per_engineering FROM verified GROUP BY location ORDER BY budget_per_engineering NULLS LAST
